import { DurableObject } from 'cloudflare:workers';
import suspendModule from './suspend.wasm';
import actorModule from './actor.wasm';

export class Probe extends DurableObject {
  async fetch() {
    const sql = this.ctx.storage.sql;
    sql.exec('CREATE TABLE IF NOT EXISTS counter (n INTEGER NOT NULL)');
    sql.exec('DELETE FROM counter');
    sql.exec('INSERT INTO counter VALUES (0)');
    let rawBegin;
    try { sql.exec('BEGIN'); rawBegin = 'accepted'; sql.exec('ROLLBACK'); }
    catch (error) { rawBegin = String(error); }
    try {
      this.ctx.storage.transactionSync(() => {
        sql.exec('UPDATE counter SET n=1');
        throw new Error('intentional rollback');
      });
    } catch (error) {
      if (error.message !== 'intentional rollback') throw error;
    }
    const rollbackValue = sql.exec('SELECT n FROM counter').one().n;
    const features = { suspending: typeof WebAssembly.Suspending, promising: typeof WebAssembly.promising };
    let jspi = null;
    if (features.suspending === 'function' && features.promising === 'function') {
      const instance = new WebAssembly.Instance(suspendModule, { env: {
        delayed: new WebAssembly.Suspending(async value => {
          await new Promise(resolve => setTimeout(resolve, 1));
          return value + 1;
        }),
      } });
      const run = WebAssembly.promising(instance.exports.run);
      const before = instance.exports.__stack_pointer.value;
      let last;
      for (let i = 0; i < 1000; i++) {
        last = await run(i);
        if (last !== 2 * i + 2) throw new Error('JSPI result mismatch');
      }
      jspi = { calls: 1000, last, stackBefore: before, stackAfter: instance.exports.__stack_pointer.value,
        memoryBytes: instance.exports.memory.buffer.byteLength };
    }
    const actor = new WebAssembly.Instance(actorModule, {}).exports;
    const input = new TextEncoder().encode('1\nlive\n0\n0\n100\nincrement\n-\n-');
    new Uint8Array(actor.memory.buffer).set(input, actor.input_ptr());
    actor.invoke(input.length);
    const output = new TextDecoder().decode(new Uint8Array(actor.memory.buffer, actor.output_ptr(), actor.output_len()));
    return Response.json({ features, rawBegin, rollbackValue, jspi,
      roc: { header: output.split('\n\n')[0], counter: output.includes('id="counter"'),
        feed: output.includes('id="counter-feed"'), arenaUsed: actor.arena_used(), memoryBytes: actor.memory.buffer.byteLength } });
  }
}
export default { fetch(request, env) { return env.PROBE.getByName('probe').fetch(request); } };
